-- A
SELECT id, round(100.0 * amount / sum(amount) OVER (), 1) AS pct
FROM sales WHERE region = 'north';

-- B
SELECT id, pct FROM (
  SELECT id, region, round(100.0 * amount / sum(amount) OVER (), 1) AS pct
  FROM sales
) s
WHERE region = 'north';

-- C
SELECT id, round(100.0 * amount / (SELECT sum(amount) FROM sales), 1) AS pct
FROM sales WHERE region = 'north';

